-- ==============================================================================
-- SEIS · ELIMINAR 57 ATENCIONES AMBULATORIAS (AM) REGISTRADAS POR ERROR · OCTUBRE 2026
-- Base: sgcoresys (servidor de producción) · Ejecutar en Adminer > Comando SQL
--
-- Tablas hijas de una atención (revisado en seis_setiembre26, 2026-11-10):
--   atencion_diagnostico  diagnósticos y procedimientos
--   atencion_responsable  médico responsable
--   atencion_evento       eventos de vigilancia (faltaba en eliminar_atenciones_fisicas.sql)
--   atencion_producto     solo la usan las atenciones de farmacia (FR); se incluye por si acaso
-- No hay claves foráneas ni triggers: MySQL no borra en cascada, por eso se borran
-- primero las hijas y al final la cabecera.
--
-- Protección: cada DELETE solo afecta atenciones AM del periodo 202610 que estén
-- en la lista. Si un ID no es AM o no es de octubre, no se borra nada de él.
--
-- Vista previa en la copia local (restauración hasta el 27/10/2026): 48 de los 57
-- IDs existen, todos AM, 202610, activos, del HOSPITAL PNP AUGUSTO B. LEGUIA
-- (00016094), con 147 diagnósticos, 49 responsables y 0 eventos. Los otros 9 IDs
-- son posteriores a la restauración y solo se pueden ver en producción.
--
-- ⚠ tabla_b1 / tabla_c1 (conteos SUSALUD) no se recalculan solas: si 202610 ya
--   se procesó, hay que volver a generarlo desde el aplicativo.
-- ==============================================================================


-- ==============================================================================
-- PASO 1 · VERIFICACIÓN (ejecutar solo este bloque y revisar el resultado)
-- Esperado: 57 atenciones, todas AM, 202610. Si sale menos de 57 o aparece otro
-- tipo o periodo, revisar antes de seguir.
-- ==============================================================================

SELECT ID_TIPO_ATENCION, ID_PERIODO, ESTADO, ID_IPRESS, COUNT(*) AS atenciones
FROM atencion
WHERE id_atencion IN (
    24784328, 24786512, 24786887, 24787064, 24788247, 24789248, 24789336, 24789481,
    24789671, 24793044, 24793108, 24793145, 24793465, 24793468, 24794281, 24795236,
    24795274, 24795377, 24795379, 24795380, 24795384, 24795387, 24795389, 24795395,
