    24800262, 24800498, 24801179, 24801524, 24801613, 24803951, 24804199, 24804675,
    24805097, 24805425, 24805626, 24807143, 24808997, 24809349, 24809843, 24809955,
    24810813, 24811050, 24812637, 24813731, 24815015, 24816777, 24816781, 24816912,
    24818236
)
GROUP BY ID_TIPO_ATENCION, ID_PERIODO, ESTADO, ID_IPRESS;

